script:
(function () {
  'use strict';
  // Future value of a lump sum plus a stream of equal deposits (time value of money).
  //   i = rate per deposit period = (1 + r/m)^(m/p) - 1 for m compounding periods and p deposits
  //   a year (e^(r/p) - 1 for continuous compounding).
  //   FV = PV(1 + i)^n + PMT[((1 + i)^n - 1) / i](1 + i if deposits are at the start of each period)
  // The script steps period by period so deposits can rise once a year.
  // Checked in Node (fv.test.js): $1,000 + $100/month at 6% monthly for 10 years = $18,207.33
  // (= 1000 x 1.005^120 + 100 x (1.005^120 - 1) / 0.005); same with deposits at the start
  // = $18,289.27; $10,000 at 5% yearly for 10 years = $16,288.95; 0% rate = plain sum; $1,000/yr
  // at 5% rising 3% a year for 10 years = growing-annuity closed form 1000 x (1.05^10 - 1.03^10) / 0.02
  // = $14,248.91; continuous 6% on $1,000 for 10 years = 1000e^0.6 = $1,822.12.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });

  // --- calc start
  function periodRate(annualRate, compPerYear, perYear) {
    if (compPerYear === 0) return Math.exp(annualRate / perYear) - 1;
    return Math.pow(1 + annualRate / compPerYear, compPerYear / perYear) - 1;
  }

  // p: pv, pmt, rate (decimal), years, freq (deposits a year), comp (0 = continuous), due (bool),
  // growth (yearly deposit increase, decimal).
  function futureValue(p) {
    var i = periodRate(p.rate, p.comp, p.freq);
    var n = Math.max(1, Math.round(p.years * p.freq));
    var bal = p.pv, startOnly = p.pv, pmt = p.pmt, deposits = 0, yDep = 0, yInt = 0, rows = [];
    for (var k = 1; k <= n; k++) {
      var interest;
      if (p.due) { bal += pmt; interest = bal * i; bal += interest; }
      else { interest = bal * i; bal += interest + pmt; }
      deposits += pmt; yDep += pmt; yInt += interest;
      startOnly *= 1 + i;
      if (k % p.freq === 0 || k === n) {
        rows.push({ year: k / p.freq, deposits: yDep, interest: yInt, balance: bal });
        yDep = 0; yInt = 0;
        if (k % p.freq === 0) pmt *= 1 + p.growth;
      }
    }
    return { fv: bal, n: n, i: i, deposits: deposits, fromStart: startOnly, fromDeposits: bal - startOnly, rows: rows };
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x, digits) {
    return (x * 100).toFixed(digits).replace(/\.?0+$/, '') + '%';
  }

  function update() {
    var pv = num('fvPresent'), pmt = num('fvDeposit'), rate = num('fvRate'), years = num('fvYears'),
        growth = num('fvGrowth');
    var freq = parseInt(document.getElementById('fvFreq').value, 10);
    var compVal = document.getElementById('fvComp').value;
    var comp = compVal === 'same' ? freq : parseInt(compVal, 10);
    var due = document.getElementById('fvTiming').value === 'begin';
    var error = document.getElementById('fvError');
    var bad = [pv, pmt, rate, years, growth].some(isNaN) || pv < 0 || pmt < 0 || rate < 0 || rate > 100 ||
              years <= 0 || years > 100 || growth < 0 || growth > 50 || pv + pmt <= 0 ||
              Math.round(years * freq) < 1;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a starting amount or a deposit (not negative), a rate from 0 to 100%, at least one deposit period and up to 100 years, and a yearly raise from 0 to 50%.';
      return;
    }
    var r = futureValue({ pv: pv, pmt: pmt, rate: rate / 100, years: years, freq: freq, comp: comp, due: due, growth: growth / 100 });
    if (!isFinite(r.fv) || r.fv > 1e15) {
      error.hidden = false;
      error.textContent = 'That result is too large to show. Try a lower rate or fewer years.';
      return;
    }
    document.getElementById('fvFuture').textContent = money.format(r.fv);
    document.getElementById('fvDeposits').textContent = money.format(r.deposits);
    document.getElementById('fvInterest').textContent = money.format(r.fv - pv - r.deposits);
    document.getElementById('fvFromStart').textContent = money.format(r.fromStart);
    document.getElementById('fvFromDeposits').textContent = money.format(r.fromDeposits);
    document.getElementById('fvCount').textContent = whole.format(pmt > 0 ? r.n : 0);
    document.getElementById('fvPeriodRate').textContent = pct(r.i, 4);
    document.getElementById('fvEffective').textContent = pct(Math.pow(1 + r.i, freq) - 1, 3);
    document.getElementById('fvSchedule').innerHTML = r.rows.map(function (row) {
      var label = Math.abs(row.year - Math.round(row.year)) < 1e-9 ? String(Math.round(row.year)) : Math.ceil(row.year) + ' (part)';
      return '<tr><td>' + label + '</td><td>' + money.format(row.deposits) + '</td><td>' +
             money.format(row.interest) + '</td><td>' + money.format(row.balance) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('fvForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
